// Fetch ingredients (from existing "Retrieve Ingredients" node)
const ingredientsData = $('Retrieve Ingredients').all().map(i => i.json);
const filteredIngredients = ingredientsData.filter(ing => ing.isEnabled);

// Parse original postback from Listen
const latestPostback = $('Listen').first().json.latestPostback || '';

// Check if it's a pagination request (contains ING_PAGE_)
let page = 1;
if (latestPostback.includes('ING_PAGE_')) {
  const parts = latestPostback.split('ING_PAGE_');
  page = parseInt(parts[1]) || 1;
}

const originalPostback = latestPostback.replace('|MORE', '').replace(/\|ING_PAGE_\d+/, '');

// Pagination: 10 ingredients per page to stay under 13 total quick replies
const itemsPerPage = 10;
const totalPages = Math.ceil(filteredIngredients.length / itemsPerPage);
const startIndex = (page - 1) * itemsPerPage;
const endIndex = startIndex + itemsPerPage;
const pageIngredients = filteredIngredients.slice(startIndex, endIndex);

const quick_replies = pageIngredients.map(ing => ({
  content_type: "text",
  title: ing.Name + " (+₱15)",
  payload: `${originalPostback}|${ing.IngredientID}`
}));

// Add navigation buttons
if (page > 1) {
  quick_replies.push({
    content_type: "text",
    title: "⬅️ Previous Page",
    payload: `${originalPostback}|MORE|ING_PAGE_${page - 1}`
  });
}

if (page < totalPages) {
  quick_replies.push({
    content_type: "text",
    title: "➡️ Next Page",
    payload: `${originalPostback}|MORE|ING_PAGE_${page + 1}`
  });
}

quick_replies.push({
  content_type: "text",
  title: "Back to Add-ons",
  payload: originalPostback
});

const responsePayload = {
  messaging_type: "RESPONSE",
  recipient: { id: senderId },
  message: {
    text: `Select an ingredient add-on (Page ${page}/${totalPages}):`,
    quick_replies: quick_replies
  }
};

return [{ json: responsePayload }];
